topics.body:
// делит и округляет вниз (к меньшему целому): 7 // 2 == 3, а -7 // 2 == -4.

% — остаток от деления: 7 % 3 == 1. Удобно проверять чётность: n % 2 == 0.

** — возведение в степень: 2 ** 10 == 1024. Знак ^ в Python — это побитовое «исключающее или», не степень.

examples.code:
score = 73
if score >= 90:
    print('A')
elif score >= 70:
    print('B')
else:
    print('C')

for ch in 'кот':
    print(ch)
print('готово')

for n in range(10):
    if n == 3:
        break
    print(n)

total = 0
for n in range(6):
    if n % 2 == 0:
        continue
    total += n
print(total)

for n in [3, 5, 7]:
    if n % 2 == 0:
        print('нашли чётное')
        break
else:
    print('все нечётные')

for i in range(1, 3):
    for j in range(1, 3):
        print(i, j)

a = {1, 2, 3}
b = {2, 3, 4}
print(sorted(a | b), sorted(a & b), sorted(a - b), sorted(a ^ b))

ages = {'Ада': 36, 'Алан': 41}
ages['Грейс'] = 85
print(ages['Алан'], len(ages))

prices = {'чай': 3, 'кофе': 5}
for name, price in prices.items():
    print(name, price)
print(prices.get('сок', 0), 'чай' in prices, 3 in prices)

counts = {}
for ch in 'abracadabra':
    counts[ch] = counts.get(ch, 0) + 1
print(counts)

def power(base, exp=2):
    return base ** exp

print(power(3), power(2, 5), power(exp=3, base=2))

def total(*nums):
    return sum(nums)

print(total(1, 2, 3), total())

def info(**options):
    for key, value in options.items():
        print(key, "=", value)

info(color="red", size=3)

def point(x, y, z=0):
    return (x, y, z)

coords = [1, 2]
print(point(*coords), point(*coords, **{"z": 5}))

def connect(host, *, timeout=5):
    return f"{host}:{timeout}"

print(connect("db", timeout=10))

def add(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

print(add("a"), add("b"))

def multiplier(k):
    def mul(x):
        return x * k
    return mul

triple = multiplier(3)
print(triple(5), multiplier(10)(4))

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def flatten(items):
    result = []
    for x in items:
        if isinstance(x, list):
            result.extend(flatten(x))
        else:
            result.append(x)
    return result

print(flatten([1, [2, [3, 4]], 5]))

from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(80))
